using System;using System.IO;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class CoffeeTextureDetail{static CoffeeTextureDetail(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeTextureDetail.request"))return;File.Delete("CoffeeTextureDetail.request");try{string path="Assets/Scenes/Oasis/3D/Texture/Building/Building-01.jpg";string backup="FinalEnvironmentRoadBackup/BeforeCoffeeTextureRepair/Building-01.jpg";Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCoffeeTextureDetail");File.Copy(path,"FinalEnvironmentRoadBackup/BeforeCoffeeTextureDetail/Building-01.jpg",true);var room=new Texture2D(2,2,TextureFormat.RGB24,false);room.LoadImage(File.ReadAllBytes("FinalEnvironmentRoadReview/Coffee-Interior-Detailed-Source.png"));var atlas=new Texture2D(2,2,TextureFormat.RGB24,false);atlas.LoadImage(File.ReadAllBytes(backup));var colors=atlas.GetPixels32();int count=0;for(int y=Mathf.FloorToInt(.500f*atlas.height);y<Mathf.CeilToInt(.751f*atlas.height);y++)for(int x=Mathf.FloorToInt(.601f*atlas.width);x<Mathf.CeilToInt(.752f*atlas.width);x++){float u=(x+.5f)/atlas.width,v=(y+.5f)/atlas.height;float vertical=u<.681f?(u-.603f)/.074f:(.750f-u)/.074f;float horizontal=Mathf.Repeat((v-.500f)/.0714f,1);var color=room.GetPixelBilinear(horizontal,Mathf.Clamp01(vertical));float edge=Mathf.Min(horizontal,1-horizontal);if(edge<.018f)color=new Color(.075f,.052f,.033f);colors[y*atlas.width+x]=color;count++;}atlas.SetPixels32(colors);atlas.Apply();File.WriteAllBytes(path,atlas.EncodeToJPG(98));UnityEngine.Object.DestroyImmediate(atlas);UnityEngine.Object.DestroyImmediate(room);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/CoffeeTextureDetail.txt","SUCCESS: existing Building-01 atlas coffee window region replaced with detailed warm cafe interior artwork. Counter, espresso machine, pastry case, cups, jars, pendant lamps and deeper room shadows. Updated pixels="+count+". Both shops share the same atlas. No mesh changes; no additional runtime texture/material; existing dimensions and compression settings retained.");File.WriteAllText("CoffeeTextureVerify.request","run");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeTextureDetail.txt",e.ToString());Debug.LogException(e);}}}
